#include <string.h>
#include <libgen.h>

#include <espeak-ng/espeak_ng.h>

static int initialized = 0;

static int SynthCallback(short *wav, int numsamples, espeak_EVENT *events) {
        /* prevent warning for unused arguments */
        (void) wav;
        (void) numsamples;
        (void) events;

        return 0;
}


